def min_operations(brackets):
    s = list(brackets)
    min_brackets = []

    if brackets.count('(') != brackets.count(')'): 
        return brackets

    first_index = s.index('(')
    last_index = first_index + brackets.count('(') - 1

    for i in range(max(-1, last_index - 5), min(first_index + 5, len(s)), 1):
        if s[i] == s[first_index]:
            min_brackets = s[first_index:i].copy() + s[i:last_index].copy() + s[i+1:]
            break

    for i in range(max(-1, first_index - 5), min(last_index + 5, len(s)), -1):
        if s[i] == s[last_index]:
            min_brackets = s[first_index:last_index].copy() + s[i:i + 1].copy() + s[i+1:last_index+1].copy()
            break

    return ''.join(min_brackets)

