from bisect import bisect_left

def handle_command(commands):
    n, h, queries = commands
    budget = 0
    heights = [h] * n
    violations = {query[3]: 0 for query in queries}
    for i in range(n):
        fees_prepopulated = violation(budget, violations, queries)
        idx = bisect_left(heights, i)
        if idx != -1:
            prices = [i + 1] * idx
            for j in range(idx, n):
                if heights[j] < i + 1:
                    prices.append(budget)
                    fee = violations[i + 1]
                    if fee != 0 or max(prices) > h:
                        budget -= fee
                    else:
                        fee = max(0, max(prices) - h)
                        violations[i + 1] -= max(0, max(prices) - h)
                        budget += min(violations[i + 1], budget)
            for price, fee in zip(prices, fees_prepopulated):
                if fee != 0:
                    violations[i + 1] += fees_prepopulated[j]
                high = i + 1
                while high <= j + 1 and heights[high] <= i + 1 <= heights[high - 1]:
                    fees_prepopulated[high - 1] += fee
                    violations[high - 1] -= fee
                    high += 1
            heights[i] = prices[i]
        if heights[i] > h:
            budget += fees_prepopulated

def violation(budget, violations, queries):
    fees = list(violations.values())
    violations.sort()
    i, j = 0, len(violations) - 1
    while i <= j:
        mid = (i + j) // 2
        if violations[mid] > budget:
            i = mid + 1
        else:
            j = mid - 1
    if violations[j] > budget:
        return 0
    else:
        return sum(violations[mid + 1:])

