from collections import defaultdict

MOD = 10**9 + 7

def lcm(a, b):
    return (a*b) // gcd(a, b)

def gcd(a, b):
    return a if b == 0 else gcd(b, a%b)

def serialize(nums, operations):
    result = [0] * (2 * len(nums))
    for i, num in enumerate(nums):
        operations[num] += 1
        result[2*i] += num
        result[2*i + 1] += num * (i < len(nums) - 1)
    return result

def deserialize(data):
    nums = []
    num_ops = defaultdict(int)
    for i in range(2):
        for j in range(2 * len(data)):
            x = data[j]
            num_ops[x] += 1
            if x % 2 == i:
                nums.append(x // x_ops)

    return nums

def optimal_operations(nums):
    memo = {}
    def dfs(start):
        if start in memo:
            return memo[start]

        operations = nums[start]
        if start + operations < len(nums):
            for step in range(start + operations, len(nums), operations * 2):
                operations += nums[step // 2]
                memo[start] = max(memo[start], nums[start] + dfs(step))
        return memo[start]

    best_ops = 0
    for i, num in enumerate(nums):
        best_ops = max(best_ops, dfs(i))
    return best_ops

def solution(T, N):
    nums = list(T)
    evens = len(T) // 2
    nums = serialize(nums, operations={})
    evens = serialize(nums, operations={})
    evens = serialize(nums, operations={})
    nums = (deserialize(nums) + deserialize(nums) + deserialize(evens)) % MOD
    evens = (deserialize(evens) + deserialize(evens)) % MOD
    best = 0
    for i in range(1, evens + 2):
        best = (best + optimal_operations(evens[:i]) % MOD) % MOD
    return best

if __name__ == "__main__":
    T = list(map(int, input().split()))
    N = int(input())
    print(solution(T, N))
