def min_correct_sequence(sequence):
    # Polycarpus has a finite sequence of opening and closing brackets
    # Method 1: Adding any bracket in any position.
    miss = 0
    for i in range(len(sequence)):
        if sequence[i] == '(':
            miss += 1
        else:
            miss -= 1
        if miss < 0:
            # In case there is only one closing bracket left when the miss exceeds to 0
            return sequence[:i] + sequence[i:].replace('(', ')', 1)

    # Method 2: Cyclic shift - moving the last bracket from the end of the sequence to the beginning.
    index = len(sequence) - sequence[::-1].index(')')
    return sequence[:index] + sequence[index:].replace('(', ')', 1)

