def get_neighbors(i, j, n):
    neighbors = []
    for y in range(j - 1, j + 2):
        if y < 0 or y >= n:
            continue
        neighbors.append((i, y))
    for x in range(i - 1, i + 2):
        if x < 0 or x >= 2:
            continue
        if x != i and (x, j) not in neighbors:
            neighbors.append((x, j))
    return neighbors

def bfs(matrix, alice_matrix):
    visited = defaultdict(lambda: -1)
    queue = deque([(0, 0)])

    while queue:
        i, j = queue.popleft()
        if i == len(matrix[0]) - 1 and j == len(matrix[0]) - 1:
            return 0

        for neighbor in get_neighbors(i, j, len(matrix[0])):
            if visited[neighbor] == -1 and matrix[neighbor[0]][neighbor[1]] == alice_matrix[neighbor[0]][neighbor[1]]:
                visited[neighbor] = i + j
                queue.append(neighbor)

    return -1

