import sys
import heapq

def zombie(puzzle1, puzzle2, m, n):
    if len(puzzle1) != m or len(puzzle2) != m or n != len(puzzle2[0]):
        return -1

    for i in range(m):
        for j in range(m):
            if puzzle1[i][j] != puzzle2[i][j]:
                return -1

    moves = 0
    visited = [[False] * n for _ in range(m)]

    def bfs(start, goal):
        queue = [(0, start, goal)]
        visited[start] = True
        while queue:
            steps, node1, node2 = heapq.heappop(queue)
            if node1 == goal:
                return steps
            for x in range(m):
                for y in range(n):
                    nei_n1 = (node1[0], x)
                    nei_n2 = (y, node2[1])
                    if (nei_n1[0] + nei_n1[1] != node1[0] + node1[1]) and (nei_n1[0] + nei_n1[1] != node2[0] + node2[1]):
                        if not visited[nei_n1[0]][nei_n1[1]]:
                            visited[nei_n1[0]][nei_n1[1]] = True
                            steps += 1
                            heapq.heappush(queue, (steps, nei_n1, nei_n2))
        return -1

    last_moves = bfs((0, 0), (m - 1, n - 1))
    if last_moves == -1:
        return -1

    moves = last_moves + bfs((m - 1, 0), (0, n - 1))
    if moves == -1:
        return -1

    return moves

