from typing import List

class PermutationGen:
    def __init__(self, n: int):
        self.n = n
        self.inv_count = 0

    def flip(self, L: int, R: int) -> int:
        if self.n % 2 == 1:
            return 0
        flipped_half = self.inv_count // 2
        L2 = (L + self.n + 1) // 2
        R2 = (R + self.n + 1) // 2
        if L < R and R2 < L2 and L2 - L < R < R2 - R:
            return flipped_half + 2
        if L <= L2 <= R2 <= R:
            return flipped_half * 2
        return flipped_half + 1

def min_inversions(permutation, query_count):
