def next_permutation(perm):
    i, j, k = len(perm) - 2, len(perm) - 1, -1
    while (i >= 0) and (perm[i] >= perm[i+1]):
        i -= 1
    if (i >= 0):
        j = i
        while (perm[j] >= perm[j + 1]):
            j -= 1 
        j += 1
    ans = list(perm)
    if (i >= 0):
        ans[i], ans[j] = ans[j], ans[i]
    i += 1
    while i < j:
        ans[i], ans[j] = ans[j], ans[i]
        i += 1
        j -= 1
    return tuple(ans)

def line_to_data(ascii_line, N):
    W = tuple(int(w) for w in ascii_line.split())
    return tuple(W[1:-1]), tuple(map(lambda x: x + 1, W[1:-1]))

def read_input():
    n = int(input())
    perm = tuple(map(int, input().split()))
    _, weights = line_to_data(input(), n)
    q = int(input())
    swaps = list(map(lambda x: tuple(map(int, x.split())), input().split()))
    return n, perm, weights, q, swaps

def legal_move(n, current_weight_line, current_permutation_line, swap):
    new_weight_line = tuple(max(*current_weight_line[i:current_permutation_line[i]-1]+current_weight_line[:current_permutation_line[i]])
                                        for i in range(len(current_permutation_line)))
    return new_weight_line

def append_result(data, swaps, permutation, results):
    next_permutation_line, next_permutation_weight = next_permutation(permutation)
    results.append(permutation)
    for ix in swaps:
        new_permutation = permutation[:ix[0]] + next_permutation_line + permutation[ix[1]:]
        new_permutation_weight = permutation[:ix[0]] + next_permutation_weight + permutation[ix[1]:]
        data.append(legal_move(n, new_permutation_weight, new_permutation, ix))

def solve():
    data, swaps, permutation, results = [], [], [], []
    (n, perm, weights, _q, q) = read_input()
    for swap in q:
        permutation[swap[0]], permutation[swap[1]] = permutation[swap[1]], permutation[swap[0]]
        results = append_result(data, swaps, permutation, results)
    return results[:]

