def can_solve(n, k, operations):
    if n > 4 or len(set([len(operation) for operation in operations])) > 1:
        return "NO"

    for operation in operations:
        if operation[0] == "mix":
            # Identify the two colors being mixed
            color1, color2, color3 = operation[2].pop(), operation[3].pop()
            if color1 != color2 and color1 != color3:
                # Check if the resulting color matches one of the primary colors
                if color1 == "R" and color2 == "Y" and color3 == "B":
                    color = "YB"
                elif color1 == "Y" and color2 == "R" and color3 == "B":
                    color = "RY"
                elif color1 == "R" and color2 == "B" and color3 == "Y":
                    color = "YR"
                elif color1 == "B" and color2 == "Y" and color3 == "R":
                    color = "YR"
                elif color1 == "B" and color2 == "R" and color3 == "Y":
                    color = "YR"
                elif color1 == "Y" and color2 == "R" and color3 == "B":
                    color = "RY"
                else:
                    return "NO"
                # Replace the remaining cells of the same color with the new color
                remaining = set(operation[2]) - {color1, color2}
                if not remaining:
                    return "NO"
                for cell in remaining:
                    operation[2][cell] = color

            elif color1 == color2 == color3:
                return "NO"
        elif operation[0] == "RY":
            # RY operation, swap red and yellow
            for cell in range(len(operation[3]) - 1, -1, -1):
                operation[3][cell] = "Y" if operation[3][cell] == "R" else "R"
        elif operation[0] == "RB":
            # RB operation, swap red and blue
            for cell in range(len(operation[3]) - 1, -1, -1):
                operation[3][cell] = "B" if operation[3][cell] == "R" else "R"
        elif operation[0] == "YB":
            # YB operation, swap yellow and blue
            for cell in range(len(operation[3]) - 1, -1, -1):
                operation[3][cell] = "B" if operation[3][cell] == "Y" else "Y"

    return "YES"

