                return False
            if (col != n - 1 and desired[row][col + 1] == 1 and desired[1 - row][col + 1] == 0):
                return False
    return True

def min_swaps_for_transform(alice_arrangement: List[List[int]], desired_arrangement: List[List[int]]) -> int:
    n = len(desired_arrangement[0])
    swap_queue: deque[tuple[int, int]] = deque()
    swaps = 0

    for row in range(2):
        for col in range(n):
            if desired_arrangement[row][col] != alice_arrangement[row][col]:
                swap_queue.append((row, col))

    # Perform swaps until all operations match
    while len(swap_queue) > 0:
        row, col = swap_queue.popleft()
        target_row, target_col = 1 - row, col
        if desired_arrangement[row][col] != desired_arrangement[target_row][target_col]:
            swaps += 1
            alice_arrangement[row][col], alice_arrangement[target_row][col] = (
                alice_arrangement[target_row][col],
                alice_arrangement[target_row][col],
            )
            alice_arrangement[target_row][col], alice_arrangement[row][col] = (
                alice_arrangement[row][col],
                alice_arrangement[row][col],
            )

    return swaps if is_possible_to_transform(desired_arrangement, alice_arrangement) else -1

