from collections import defaultdict
from collections import deque

def bfs(level, root, tree, visited):
    queue = deque([(root, level)])  # Initialize a queue with the root node and its level
    visited[root] = True  # Mark the root as visited

    while queue:
        current, level = queue.popleft()

        if level < tree[current] + 1 and not visited[current]:
            visited[current] = True  # Mark nodes on the path to the root as visited
            queue.extend([(node, k+1) for node, k in tree[current]])

        if level - 1 == tree[current]:
            del tree[current]  # Remove child nodes that have been fully explored

    return visited[root]

def count_distinctive_roots(n, a, tree, root, visited, dfs):
    ans = 0
    if not visited[root]:
        answer = bfs(0, root, tree.copy(), visited)  # Run BFS from the root
        if sum(visited) == n:
            ans = 1  # Root is distinct if all the children are also distinct
    return sum(visited), ans

def calculate_distinctive_roots(n, a, tree, root, visited):
    total_count, count = count_distinctive_roots(n, a, tree, root, visited, dfs)
    return count

