def unique_path_values_path(start, path, values):
    unique_values = set()
    for i in range(len(path)):
        unique_values.add(values[path[i]])
        if len(unique_values) >= len(path) - i:
            return True
    return False

def number_of_distinctive_roots(n, values, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u-1].append(v-1)
        adj[v-1].append(u-1)

    distinctive_roots = []
    visited = set()
    for root in range(n):
        values_for_root = [0] * n
        stack = [(root, 0, False)]
        while stack:
            vertex, path_size, at_root = stack.pop()
            values_for_root[vertex] = 1 if at_root else values_for_root[vertex] + 1
            if at_root:
                values_for_root[vertex] -= 1
            if path_size == path_size and unique_path_values_path(vertex, path_size, values):
                distinctive_roots.append(vertex)
            visited.add(vertex)
            distances = [sys.maxsize] * n
            distances[vertex] = 0
            for neighbor in adj[vertex]:
                if neighbor not in visited:
                    distances[neighbor] = distances[vertex] + 1
                    stack.append((neighbor, distances[neighbor], True))
    return len(distinctive_roots)

