def count_distinctive_roots(n, values, edges):
    """
    :param n: Number of vertices in the tree.
    :param values: List of values associated with each vertex.
    :param edges: List of tuples representing the edges in the tree.
    :return: Number of distinctive roots in the tree.
    """
    from collections import defaultdict

    # Classify vertices into two categories using Union-Find
    def union_find(x, y, parent, rank):
        if parent[x] != x:
            parent[x] = union_find(parent[x], parent[y], parent, rank)
        return parent[x]

    def classify(parent, rank, x, y):
        c1, c2 = set(), set()
        parent1 = union_find(x, y, parent, rank)
        rank1, rank2 = rank[parent1], rank[union_find(x, y, parent, rank)]
        if rank1 > rank2:
            for small_rank in range(rank1, 0, -1):
                c1.add(parents[small_rank])
            for small_rank in range(rank2):
                c1.add(rank2)
        elif rank1 < rank2:
            for small_rank in range(rank2, 0, -1):
                c1.add(rank2)
            for small_rank in range(rank1):
                c1.add(parents[small_rank])
        else:
            c1.add(rank2)
            c2.add(parents[0])
        return c1.union(c2)

    edges_copy = [(y, x) for x, y in edges]
    rank, parents = [0] * n, defaultdict(int)

    # Each tree is one category for the classification
    for edge in edges:
        parents[edge[0]] = edge[1]

    # Different category from each other, remove common result from the union
    if len(edges) >= 2 and len(edges) % 2 == 0:
        return 0

    # Classify first 
    _classify = classify(parents, rank, *[x for x in edges])
    return len(_classify)

