def d_sort(sub):
    s = list(sub)
    i = j = 0
    while i < len(s) and j + 1 < len(s):
        k = j + 1
        while j < len(s) - 1 > k and s[k].isdigit() and s[k + 1].isdigit():
            k += 2
        if s[k].isdigit() and s[k + 1].isdigit():
            s[k], s[k + 1] = s[k + 1], s[k]
        for x in range(j, k):
            s[i], s[x] = s[x], s[i]
        i += 1
        j += 2
    return ''.join(s)

def process_sub(s, k, d):
    sub = s[:k]
    sorted_sub = d_sort(sub)
    s = s[k:]
    for i in range(0, len(s), d):
        if sorted_sub:
            s = s[:i + 1] + sorted_sub + s[i + 1:]
    return s

