    if T == 'P':
        step = dijkstra(c1, cR)
    else:
        step = 0
        max_steps = 10**9
        max_weights = []
        for weights in graph[T]:
            weight = dijkstra(c1, weights[0]) + dijkstra(weights[0], cR)
            print('debug', weight)
            if weight <= max_steps:
                max_steps = weight
                max_weights = weights
            elif weight == max_steps:
                max_weights += weights
        step += min(max_weights, key=lambda x: x[1])
        step += dijkstra(c1, step[0]) + dijkstra(step[0], step[1])
    print(modular_n(step, N), len(max_weights))
