from collections import defaultdict

def mix_colors(colors, order, result_col):
    """
    Mixes cells in the given order to produce the specified result color.
    """
    for color_index, next_index in enumerate(order):
        if colors[next_index - 1] + result_col == result_col:
            return "YES"
        else:
            if colors[next_index - 1] == "R":
                colors[next_index - 1] = "Y"
                colors[next_index - 1 - order[color_index]] = "R"
            elif colors[next_index - 1] == "Y":
                colors[next_index - 1] = "B"
                colors[next_index - 1 - order[color_index]] = "Y"
            elif colors[next_index - 1] == "B":
                colors[next_index - 1] = "R"
                colors[next_index - 1 - order[color_index]] = "B"
            elif colors[next_index - 1] == "W":
                return "NO"
    return "NO"

def find_initial_colors(n: int, k: int, descriptions: list):
    operations = defaultdict(list)
    for description in descriptions:
        name, m, *indexes = description.split()
        for index in indexes:
            operations[name].append(int(index))

    colors = ["R", "Y", "B", "W"]
    for operation_name in operations.keys():
        if operation_name not in ["mix", "RY", "RB", "YB"]:
            return "NO"

    for mix_index, m, indexes in descriptions:
        if operation_name == "mix":
            result_col = mix_colors(colors[:n], indexes, operation_name)
            if not result_col:
                return "NO"
        else:
            colors[indexes[mx - 1]] = operations[operation_name][-1]

    for color in colors:
        if color not in operation_name:
            return "NO"

    return "YES"

n, k = map(int, input().split())
