def d_sort(s, d):
    """
    Returns the string after applying d-sorting to s.
    """
    length = len(s)
    if d < 1:
        return s
    indices = [i for i in range(length)]  # Base array for storing internal array indexes
    for i in range(length):
        indices[i] = (i % d) % d  # Every integer x goes to [(x*d)%d][(x*d)%d]%d
    store = [[] for _ in range(d)]
    for i in range(length):
        store[indices[i]].append(s[i])
    result = []
    for i in range(d):
        while store[i]:
            result.append(store[i].pop(0))
    return ''.join(result)

def process_k_and_d(s, k, d, indices):
    """
    Replaces 'k' length substring from 'i' index to 'i + k - 1' of s
    by the result of d-sorting that substring.
    """
    result = []
    for i in range(0, k, d):
        result.extend(d_sort(s[i:i + d], d))
    return ''.join(result)

