from collections import deque

def shortestPath(graph, start, end):
    queue = deque([(0, start)])
    visited = set([start])

    while queue:
        steps, current = queue.popleft()
        if current == end:
            return steps
        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((steps + 1, neighbor))

    return -1

def solve(n):
    if n % 2 != 0:
        return 'dead'

    aliceArrangement = list(map(int, input().strip().split()))
    friendArrangement = list(map(int, input().strip().split()))
    totalSteps = 0

    for i in range(n):
        if aliceArrangement[i] != friendArrangement[i]:
            if i == 0:
                totalSteps += shortestPath(zip(friendArrangement, aliceArrangement[1:]), (friendArrangement[0], friendArrangement[1]))
            elif i == n-1:
                totalSteps += shortestPath(zip(friendArrangement, aliceArrangement[:-1]), (friendArrangement[-1], aliceArrangement[-2]))
            elif i == n-2 or i == 0:
                totalSteps += shortestPath(zip(friendArrangement, aliceArrangement[:-2]), (friendArrangement[-2], friendArrangement[-1]))
            else:
                totalSteps += shortestPath(zip(friendArrangement, aliceArrangement[:-n//2]), (friendArrangement[-n//2], aliceArrangement[-n//2]))

    return totalSteps if totalSteps > 0 else -1

n = int(input().strip())
print(solve(n))

