def max_goods(budget, goods):
    n = len(goods)
    dp = [budget] + [0] * budget

    for i in range(1, budget + 1):
        for j in range(n-1, -1, -1):
            if i >= goods[j][0]:
                use_coupon = goods[j][2] + (goods[j][0] - i)
                remaining_budget = dp[i - goods[j][0]]
                if use_coupon + remaining_budget <= budget:
                    dp[i] = max(dp[i], use_coupon + remaining_budget)

    return budget - min(dp) if min(dp) <= budget else 0

